mutations.before:
if (destination !== undefined) {
  const bundleText = new TextDecoder().decode(bundle);
  if (!bundleText.includes(CLICK_TAG_VARIABLE)) {
    throw new Error(
      `HTML asset ${assetIdentity(asset)} has clickDestination but bundle is missing "${CLICK_TAG_VARIABLE}" variable declaration.`,
    );
  }
}

...(isHtml
              ? {
                  format: "html",
                  htmlBundlePath,
                  htmlFallbackPath,
                  ...(brief.clickDestination !== undefined
                    ? { clickDestination: brief.clickDestination }
                    : {}),
                }
              : {}),

function safeBrandColor(brandColor: string): string {
  if (!isBrandColor(brandColor)) {
    throw new Error(
      `assembleHtml: brandColor must be a 6-digit hex colour like "#1473E6", got ${JSON.stringify(brandColor)}`,
    );
  }
  return escapeHtml(brandColor);
}

mutations.after:
function safeBrandColor(brandColor: string): string {
  return brandColor;
}
